export const attorneyBySlug = (slug: string) =>
  attorneys.find((a) => a.slug === slug);

/**
 * The attorneys who LEAD a practice area, for the "Handled by" block.
 * Returns nothing for the criminal hubs by design; see `leadsPracticeHrefs`.
 */
export const attorneysLeadingPractice = (href: string) =>
  attorneys.filter((a) => a.leadsPracticeHrefs?.includes(href));

/** The attorneys who handle a charge page (D65); see `handlesChargeHrefs`. */
export const attorneysHandlingCharge = (href: string) =>
  attorneys.filter((a) => a.handlesChargeHrefs?.includes(href));

